115: static int cpu_vector_available(int cpu)
116: {
117: 	int vector, max_vector = 256;
118: 	int avl_vector = 0;
119: 
120: 	for (vector = 0; vector < max_vector; vector++)
121: 		if (per_cpu(vector_irq, cpu)[vector] == 0)
122: 			avl_vector++;
123: 
124: 	return avl_vector;
125: }
126: 
127: static int cpu_vector_tomove(int cpu)
128: {
129: 	int max_vector = 256;
130: 
131: 	return max_vector - cpu_vector_available(cpu);
132: }
133: 
134: static int vector_available(void)
135: {
136: 	int cpu, avl_vector = 0;
137: 
138: 	for_each_online_cpu(cpu)
139: 		avl_vector += cpu_vector_available(cpu);
140: 
141: 	return avl_vector;
142: }
