144: int can_unplug_cpu(void)
145: {
146: 	unsigned int free, tomove;
147: 	unsigned int cpu = smp_processor_id();
148: 
149: 	tomove = cpu_vector_tomove(cpu);
150: 	free = vector_available();
151: 	if (free < tomove) {
152: 		pr_info("CPU %u has %u vectors, %u available, Cannot disable CPU\n",
153: 				cpu, tomove, free);
154: 		return -ENOSPC;
155: 	}
156: 
157: 	return 0;
158: }
159: #else
160: int can_unplug_cpu(void) { return 0; }
