164: void __init init_IRQ(void)
165: {
166: 	/*
167: 	 * Just in case the platform init_irq() causes interrupts/mchecks
168: 	 * (as is the case with RAWHIDE, at least).
169: 	 */
170: 	struct page __maybe_unused *nmi_stack_page = alloc_pages_node(
171: 		cpu_to_node(smp_processor_id()),
172: 		THREADINFO_GFP, THREAD_SIZE_ORDER);
173: 	unsigned long nmi_stack __maybe_unused = nmi_stack_page ?
174: 		(unsigned long)page_address(nmi_stack_page) : 0;
175: 
176: 	wrent(entInt, 0);
177: 	if (IS_ENABLED(CONFIG_SUBARCH_C4) && is_in_host()) {
178: 		sw64_write_csr_imb(nmi_stack + THREAD_SIZE, CSR_NMI_STACK);
179: 		wrent(entNMI, 6);
180: 		set_nmi(INT_PC);
181: 	}
182: 
183: 	sunway_init_pci_intx();
184: 	irqchip_init();
185: }
